// Synchronous path is schema validation only. Normalization, INN checksum, dedup in CRM: 02 process.
const body = $json.body;
const headers = $json.headers ?? {};
const errors = [];
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const str = (v, max) => typeof v === 'string' && v.trim().length > 0 && v.length <= max;
const opt = (path, v, max) => { if (v !== undefined && v !== null && !str(v, max)) errors.push(`${path}: string 1..${max} expected`); };

if (!isObj(body)) {
  errors.push('body: JSON object expected');
} else {
  if (JSON.stringify(body).length > 32768) errors.push('body: larger than 32 KB');
  if (!['web', 'telegram', 'email', 'api'].includes(body.source)) errors.push('source: one of web|telegram|email|api');
  if (!isObj(body.contact)) {
    errors.push('contact: object required');
  } else {
    opt('contact.name', body.contact.name, 200);
    opt('contact.phone', body.contact.phone, 50);
    opt('contact.email', body.contact.email, 254);
    if (!body.contact.phone && !body.contact.email) errors.push('contact: phone or email required');
  }
  if (body.company !== undefined) {
    if (!isObj(body.company)) errors.push('company: object expected');
    else {
      opt('company.name', body.company.name, 300);
      if (body.company.inn !== undefined && !/^\d{10}(\d{2})?$/.test(String(body.company.inn))) errors.push('company.inn: 10 or 12 digits');
    }
  }
  opt('message', body.message, 5000);
  opt('region', body.region, 100);
  opt('product', body.product, 100);
  if (body.utm !== undefined && !isObj(body.utm)) errors.push('utm: object expected');
}

// Idempotency key: explicit header wins; otherwise the source's own id.
const headerKey = headers['idempotency-key'];
let key = null;
if (headerKey !== undefined) {
  if (!str(headerKey, 200)) errors.push('Idempotency-Key header: string 1..200');
  else key = `hdr:${headerKey.trim()}`;
} else if (isObj(body)) {
  if (!str(body.external_id === undefined ? undefined : String(body.external_id), 200)) errors.push('external_id: required when no Idempotency-Key header');
  else key = `${body.source}:${String(body.external_id).trim()}`;
}

return { json: { valid: errors.length === 0, errors, idempotency_key: key, source: body?.source ?? null, payload: body ?? null } };
